begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;select no_plan();
select ok((select bool_and(rowsecurity) from pg_tables where schemaname='public' and tablename in ('academic_closures','group_schedule_exceptions','academic_calendar_events','lesson_generation_skips')),'Calendar tables enforce RLS');
select ok(not has_table_privilege('authenticated','public.academic_closures','insert'),'Calendar mutations require checked commands');
select ok(not has_table_privilege('authenticated','public.academic_calendar_events','select'),'Raw calendar audit is private');
select ok(not has_function_privilege('anon','public.save_academic_closure(uuid,uuid,uuid,integer,jsonb)','execute'),'Anonymous closure commands are revoked');
create temporary table academic_scope(label text primary key,id uuid);
grant select,insert on academic_scope to authenticated;
create function pg_temp.sid(text) returns uuid language sql stable as $$select id from academic_scope where label=$1$$;
create function pg_temp.day(integer) returns text language sql stable as $$select ((now() at time zone 'Asia/Tashkent')::date+$1)::text$$;
insert into auth.users(id,email,email_confirmed_at) values('99999400-0000-0000-0000-000000000001','native-calendar-owner@example.test',now()),('99999400-0000-0000-0000-000000000002','native-calendar-teacher@example.test',now()),('99999400-0000-0000-0000-000000000003','native-calendar-foreign@example.test',now());
set local role authenticated;
set local request.jwt.claim.sub='99999400-0000-0000-0000-000000000001';
insert into academic_scope values('tenant',public.create_business('Native academic integration'));
insert into academic_scope select 'branch',id from public.branches where tenant_id=pg_temp.sid('tenant') limit 1;
insert into academic_scope values('course',public.save_course(pg_temp.sid('tenant'),null,gen_random_uuid(),0,'{"name":"Academic integration course","standard_price":"750000.10","pricing_model":"monthly"}'));
insert into academic_scope values('group',public.save_study_group(pg_temp.sid('tenant'),null,gen_random_uuid(),0,jsonb_build_object('name','Original student group','course_id',pg_temp.sid('course'),'branch_id',pg_temp.sid('branch'),'start_date',pg_temp.day(-30),'capacity','1')));
insert into academic_scope values('teacher',public.save_employee(pg_temp.sid('tenant'),null,'Native integration teacher','','native-calendar-teacher@example.test','Teacher','active',pg_temp.day(0)::date,'',array[pg_temp.sid('branch')]));
insert into academic_scope values('role',(select id from public.business_roles where tenant_id=pg_temp.sid('tenant') and system_key='teacher'));
create temporary table academic_token(token text);
grant select,insert on academic_token to authenticated;
insert into academic_token select public.create_employee_invitation(pg_temp.sid('tenant'),pg_temp.sid('teacher'),pg_temp.sid('role'));
set local request.jwt.claim.sub='99999400-0000-0000-0000-000000000002';
select public.accept_employee_invitation((select token from academic_token));
set local request.jwt.claim.sub='99999400-0000-0000-0000-000000000001';
select public.set_group_teachers(pg_temp.sid('tenant'),pg_temp.sid('group'),gen_random_uuid(),1,array[pg_temp.sid('teacher')],pg_temp.sid('teacher'));
select public.change_group_status(pg_temp.sid('tenant'),pg_temp.sid('group'),gen_random_uuid(),2,'active','Activate original student group');
insert into academic_scope values('student',public.save_student(pg_temp.sid('tenant'),gen_random_uuid(),null,'{"first_name":"Original native student","phone":"9989088181"}','{}',array[pg_temp.sid('branch')]));
insert into academic_scope values('enrollment',public.create_student_enrollment(pg_temp.sid('tenant'),pg_temp.sid('group'),pg_temp.sid('student'),gen_random_uuid(),jsonb_build_object('enrollment_date',pg_temp.day(0),'effective_start_date',pg_temp.day(-10),'status','active','agreed_price','9007199254740993.12','pricing_model','monthly')));
insert into academic_scope values('slot',public.save_group_schedule(pg_temp.sid('tenant'),pg_temp.sid('group'),null,gen_random_uuid(),0,jsonb_build_object('weekday',extract(isodow from pg_temp.day(7)::date)::integer::text,'start_time','10:00','end_time','11:00','timezone','Asia/Tashkent','effective_from',pg_temp.day(7),'effective_to',pg_temp.day(28),'teacher_id',pg_temp.sid('teacher')),'Native weekly calendar'));
insert into academic_scope select 'series',series_id from public.group_schedule_slots where id=pg_temp.sid('slot');
create temporary table calendar_values(label text primary key,value jsonb);grant select,insert on calendar_values to authenticated;
insert into calendar_values values('first',public.generate_group_lessons(pg_temp.sid('tenant'),pg_temp.sid('group'),gen_random_uuid(),pg_temp.day(7),pg_temp.day(14)));
select is((select value->>'created_count' from calendar_values where label='first'),'2','Initial real weekly lessons are generated');
insert into academic_scope select 'original',id from public.lessons where tenant_id=pg_temp.sid('tenant') and occurrence_date=pg_temp.day(7)::date;
insert into academic_scope values('closure',public.save_academic_closure(pg_temp.sid('tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',pg_temp.sid('branch'),'name','Native branch holiday','reason','Explicit branch holiday','from_date',pg_temp.day(7),'to_date',pg_temp.day(7),'is_active',true)));
select is(public.lesson_details(pg_temp.sid('tenant'),pg_temp.sid('original'))->'lesson'->>'status','scheduled','New closure does not automatically cancel existing lessons');
select is(public.closure_lesson_impact(pg_temp.sid('tenant'),pg_temp.sid('closure'))->>'total','1','Existing affected lesson is visible through checked impact query');
select is(public.lesson_calendar_context(pg_temp.sid('tenant'),pg_temp.sid('original'))->>'blocked','true','Lesson receives an active closure warning');
select throws_ok($$select public.save_lesson(pg_temp.sid('tenant'),pg_temp.sid('group'),null,gen_random_uuid(),0,jsonb_build_object('local_start',pg_temp.day(7)||'T12:00','local_end',pg_temp.day(7)||'T13:00','timezone','Asia/Tashkent','teacher_id',pg_temp.sid('teacher'),'title','Invalid closure booking'),'Direct closure conflict')$$,'P0001',null,'New manual lesson cannot bypass a closure');
insert into academic_scope values('global',public.save_academic_closure(pg_temp.sid('tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',null,'name','Native business holiday','reason','Explicit business holiday','from_date',pg_temp.day(21),'to_date',pg_temp.day(21),'is_active',true)));
insert into academic_scope values('exception',public.save_schedule_exception(pg_temp.sid('tenant'),null,gen_random_uuid(),0,jsonb_build_object('series_id',pg_temp.sid('series'),'occurrence_date',pg_temp.day(28),'reason','One occurrence only','is_active',true)));
insert into calendar_values values('receipt',public.generate_group_lessons(pg_temp.sid('tenant'),pg_temp.sid('group'),'99999400-0000-0000-0000-000000000010',pg_temp.day(7),pg_temp.day(28)));
select is((select value->>'existing_count' from calendar_values where label='receipt'),'2','Previously generated lessons remain existing occurrences');
select is((select value->>'closure_count' from calendar_values where label='receipt'),'1','Generation counts an unmaterialized holiday skip');
select is((select value->>'exception_count' from calendar_values where label='receipt'),'1','Generation counts an explicit occurrence exception');
select is((select value->>'created_count' from calendar_values where label='receipt'),'0','Closed/skipped dates do not create fake cancelled lessons');
select is(public.generate_group_lessons(pg_temp.sid('tenant'),pg_temp.sid('group'),'99999400-0000-0000-0000-000000000010',pg_temp.day(7),pg_temp.day(28))::text,(select value::text from calendar_values where label='receipt'),'Matching request returns its original immutable receipt');
select is(public.generation_skip_directory(pg_temp.sid('tenant'),(select (value->>'id')::uuid from calendar_values where label='receipt'))->>'total','2','Receipt exposes retained skip records');
select is(public.academic_closure_details(pg_temp.sid('tenant'),pg_temp.sid('global'))->'closure'->>'timezone','Asia/Tashkent','Closure stores an explicit retained timezone');
select throws_ok($$delete from public.academic_closures$$,'42501',null,'Tenant clients cannot erase calendar history');
select throws_ok($$select public.save_academic_closure(pg_temp.sid('tenant'),pg_temp.sid('closure'),gen_random_uuid(),0,jsonb_build_object('branch_id',pg_temp.sid('branch'),'name','Native branch holiday','reason','Stale calendar update','from_date',pg_temp.day(7),'to_date',pg_temp.day(7),'is_active',true))$$,'40001',null,'Stale calendar version is rejected');
select public.transition_lesson(pg_temp.sid('tenant'),pg_temp.sid('original'),gen_random_uuid(),1,'cancelled','Explicit lesson cancellation');
select is(public.lesson_calendar_context(pg_temp.sid('tenant'),pg_temp.sid('original'))->'cancellation'->>'previous_status','scheduled','Cancellation retains its previous status');
select is(public.lesson_calendar_context(pg_temp.sid('tenant'),pg_temp.sid('original'))->'cancellation'->>'reason','Explicit lesson cancellation','Cancellation retains the explicit reason');
select is(public.generate_group_lessons(pg_temp.sid('tenant'),pg_temp.sid('group'),gen_random_uuid(),pg_temp.day(7),pg_temp.day(7))->>'created_count','0','Generation never resurrects the cancelled original');
select public.save_academic_closure(pg_temp.sid('tenant'),pg_temp.sid('global'),gen_random_uuid(),1,jsonb_build_object('branch_id',null,'name','Native business holiday','reason','Explicit business holiday','from_date',pg_temp.day(21),'to_date',pg_temp.day(21),'is_active',false));
select is(public.generate_group_lessons(pg_temp.sid('tenant'),pg_temp.sid('group'),gen_random_uuid(),pg_temp.day(21),pg_temp.day(21))->>'created_count','1','Explicit reopening restores an unmaterialized eligible occurrence');
select is(public.generation_batch_details(pg_temp.sid('tenant'),(select (value->>'id')::uuid from calendar_values where label='receipt'))->>'closure_count','1','Original receipt survives later calendar edits');
set local request.jwt.claim.sub='99999400-0000-0000-0000-000000000002';
select is(public.academic_closure_details(pg_temp.sid('tenant'),pg_temp.sid('closure'))->>'can_manage','false','Teacher reads a holiday without calendar-management rights');
select throws_ok($$select public.save_academic_closure(pg_temp.sid('tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',pg_temp.sid('branch'),'name','Teacher escalation','reason','No holiday permission','from_date',pg_temp.day(30),'to_date',pg_temp.day(30),'is_active',true))$$,'42501',null,'Teacher cannot create closures');
select throws_ok($$select public.save_schedule_exception(pg_temp.sid('tenant'),pg_temp.sid('exception'),gen_random_uuid(),1,jsonb_build_object('series_id',pg_temp.sid('series'),'occurrence_date',pg_temp.day(28),'reason','No schedule management','is_active',false))$$,'42501',null,'Teacher cannot mutate weekly exceptions');
select throws_ok($$select public.generation_skip_directory(pg_temp.sid('tenant'),(select (value->>'id')::uuid from calendar_values where label='receipt'))$$,'42501',null,'Teacher cannot read a restricted generation receipt');
set local request.jwt.claim.sub='99999400-0000-0000-0000-000000000003';
select throws_ok($$select public.academic_closure_details(pg_temp.sid('tenant'),pg_temp.sid('closure'))$$,'42501',null,'Foreign closure IDs cannot bypass tenant isolation');
select is((select count(*) from public.academic_closures),0::bigint,'Foreign closure rows are hidden by RLS');
set local request.jwt.claim.sub='';
select throws_ok($$select public.academic_closure_details(pg_temp.sid('tenant'),pg_temp.sid('closure'))$$,'42501',null,'Subjectless requests cannot read calendar data');
reset role;
select is((select count(*) from public.lesson_attendance_records where tenant_id=pg_temp.sid('tenant')),0::bigint,'Skipping/cancelling creates no attendance absences');
select is((select count(*) from public.invoice_receivable_entries where tenant_id=pg_temp.sid('tenant')),0::bigint,'Calendar changes create no tuition receivables');
set constraints all immediate;
select * from finish();
rollback;
